/* 命定之诗Galgame 5.0 — Tavern Helper 4.9.5. No remote runtime. */
(function () {
  'use strict';
  const VERSION = '5.7.0';
  const BUTTON = '启动命定Galgame';
  const KEY = '__MINGDING_READER_V3__';
  function splitText(value) {
    const lines = String(value || '').trim().split(/
+|(?=\[(?:旁白|[^\]
]{1,30})\])/).map(s => s.trim()).filter(Boolean);
    return lines.flatMap(line => {
      const match = line.match(/^\[([^\]]{1,30})\]\s*([\s\S]*)$/);
      const speaker=match ? match[1] : /^[「“]/.test(line) ? '对话' : '旁白';
      const body=match ? match[2] : line;
      return (body.match(/[^。！？!?]+[。！？!?]+[”」』]?|[^。！？!?]+$/g)||[body]).map(text=>({speaker,text:text.trim()})).filter(p=>p.text);
    });
  }
  function latestState(messages) {
    for (let i = messages.length - 1; i >= 0; i--) {
      const value = messages[i].data;
      if (value && value.stat_data && typeof value.stat_data === 'object' && Object.keys(value.stat_data).length) {
        return { floor: messages[i].message_id, data: value.stat_data };
      }
    }
    return null;
  }
  function matchesSubmittedUser(message, text) { return message?.role==='user' && String(message.message||'').includes(text); }
  if (typeof module !== 'undefined' && module.exports) module.exports = { splitText, latestState, matchesSubmittedUser };
  if (typeof window === 'undefined') return;
  /* Galgame image rules. Pure logic shared by the build and offline tests. */
const MDG_ASSETS = (() => {
  const IMAGE = /\.(?:png|jpe?g|webp|gif|avif)$/i;
  const DEFAULT = { repo: 'Lao-Y/xh', branch: 'main', rules: [] };

  function config(value) {
    const input = value && typeof value === 'object' ? value : {};
    return {
      repo: /^[\w.-]+/[\w.-]+$/.test(String(input.repo || '')) ? input.repo : DEFAULT.repo,
      branch: /^[\w./-]+$/.test(String(input.branch || '')) && !String(input.branch).includes('..') ? input.branch : DEFAULT.branch,
      rules: Array.isArray(input.rules) ? input.rules.filter(r => r && typeof r === 'object').slice(0, 1000) : [],
    };
  }

  function gitUrl(settings, path) {
    const c = config(settings);
    const parts = String(path || '').replace(/\/g, '/').split('/');
    if (!parts.length || parts.some(p => !p || p === '.' || p === '..') || !IMAGE.test(parts.at(-1))) return null;
    return 'https://raw.githubusercontent.com/' + c.repo + '/' + c.branch.split('/').map(encodeURIComponent).join('/') + '/' + parts.map(encodeURIComponent).join('/');
  }

  function matches(value, needle, mode) {
    const source = String(value || '').trim().toLocaleLowerCase();
    const wanted = String(needle || '').trim().toLocaleLowerCase();
    if (!wanted) return false;
    if (mode === 'exact') return source === wanted;
    if (mode === 'prefix') return source.startsWith(wanted);
    return source.includes(wanted);
  }

  function parseTp(text) {
    const blocks = [...String(text || '').matchAll(/<tp>\s*([\s\S]*?)\s*</tp>/gi)];
    const body = blocks.at(-1)?.[1]?.replace(/\s+/g, ' ').trim();
    const match = body?.match(/^(.+?)\s*@\s*(.+?)(?:\s*\|\s*(.*))?$/);
    return match ? { time: match[1].trim(), location: match[2].trim(), weather: (match[3] || '').trim() } : null;
  }

  function period(time) {
    const value = String(time || '');
    const hour = value.match(/(?:^|[^\d])(\d{1,2}):[0-5]\d(?:\D|$)/);
    if (hour) return Number(hour[1]) >= 18 || Number(hour[1]) < 6 ? 'night' : 'day';
    if (/凌晨|深夜|午夜|夜晚|夜间|入夜|傍晚|黄昏/.test(value)) return 'night';
    if (/清晨|早晨|上午|中午|午后|下午|白天|日间/.test(value)) return 'day';
    return '';
  }

  function choosePath(rule, random = Math.random) {
    const paths = Array.isArray(rule?.paths) ? rule.paths : [rule?.path];
    const valid = paths.filter(path => typeof path === 'string' && path.trim());
    return valid.length ? valid[Math.min(valid.length - 1, Math.floor(random() * valid.length))] : null;
  }

  function pick(rules, kind, context) {
    const key = kind === 'background' ? context.location : context.speaker;
    const detail = [context.appearance, context.outfit].filter(Boolean).join(' ');
    return (Array.isArray(rules) ? rules : [])
      .map((rule, index) => ({ rule, index }))
      .filter(({ rule }) => rule.enabled !== false && rule.kind === kind &&
        (kind !== 'background' || !rule.period || !context.period || rule.period === context.period) &&
        matches(key, rule.keyword, rule.mode) &&
        (!rule.variant || matches(detail, rule.variant, 'contains')))
      .sort((a, b) => (Number(b.rule.priority) || 0) - (Number(a.rule.priority) || 0) ||
        String(b.rule.keyword).length - String(a.rule.keyword).length || a.index - b.index)[0]?.rule || null;
  }

  return { DEFAULT, config, gitUrl, matches, parseTp, period, choosePath, pick };
})();
if (typeof module !== 'undefined' && module.exports) module.exports = MDG_ASSETS;

  const host = window.parent, doc = host.document;
  if (host[KEY]) host[KEY].destroy();
  const disposers = [];
  let opened = false, destroyed = false, messages = [], queue = [], cursor = 0, floor = null;
  let chatKey = '', liveNode = null, lifted = [], scrollState = [];
  let autoTimer = null, refreshTimer = null, sending = false, lastFocus = null, textSize = 22;
  const root = doc.createElement('section'); root.id = 'mdg-reader'; root.dataset.version = VERSION;
  root.setAttribute('aria-label', '命定之诗 Galgame 舞台'); root.hidden = true;
  const style = doc.createElement('style'); style.id = 'mdg-reader-style';
  style.textContent = "html:has(#mdg-reader:not([hidden])) { transform:none!important; perspective:none!important; overflow:hidden!important }
#mdg-reader, #mdg-reader * { box-sizing:border-box }
#mdg-reader[hidden], #mdg-scrim[hidden], #mdg-reader [hidden], #mdg-scrim [hidden] { display:none!important }
