  display:grid; grid-template-rows:auto minmax(0,1fr) auto;
  padding:max(16px,env(safe-area-inset-top)) clamp(20px,4vw,64px) max(15px,env(safe-area-inset-bottom));
  gap:clamp(8px,1.5vh,18px); color:var(--mdg-text); font:14px/1.5 'Microsoft YaHei',sans-serif;
  pointer-events:none;
}
#mdg-reader button, #mdg-reader input, #mdg-reader select, #mdg-reader textarea { box-sizing:border-box; font:inherit; color:inherit; pointer-events:auto }
